"""
	Returns the belonging of the instances to the classes

	param rows -- the dataset in the current branch, the class is the argument
	in the last column

	"""
def uniquecounts(rows: Any) -> object {
    results = {};
    for row in rows {
        r = row[(len(row) - 1)];
        if (r not in results) {
            results[r] = 0;
        }
        results[r] += 1;
    }
    return results;
}

"""Checks if given bytes object contains only uppercase elements.

    Compiling bytes.isupper compiles this function.
    This function is only intended to be executed in this compiled form.

    Args:
        x: The bytes object to examine.

    Returns:
        Result of check.
    """
def bytes_isupper(x: bytes) -> bool {
    found_upper = False;
    for i in x {
        if (ord('A') <= i <= ord('Z')) {
            found_upper = True;
        } elif (ord('a') <= i <= ord('z')) {
            return False;
        }
    }
    return found_upper;
}

"""Checks if words two can be pronounced the same way.

    If either word is not in the pronouncing dictionary, return False

    a, b: strings
    phonetic: map from words to pronunciation codes
    """
def homophones(a: Any, b: Any, phonetic: Any) -> object {
    if ((a not in phonetic) or (b not in phonetic)) {
        return False;
    }
    return (phonetic[a] == phonetic[b]);
}

