    >>> reverse_iter([1, 2, 3, 4])
    [4, 3, 2, 1]
    """
def reverse_iter(lst: Any) -> object {
    reverse = [];
    for item in lst {
        reverse.insert(0, item);
    }
    return reverse;
}

"""Find a substring by Knuth-Morris-Pratt

    :param s: the haystack string
    :param t: the needle string
    :returns: index i such that s[i: i + len(t)] == t, or -1
    :complexity: O(len(s) + len(t))
    """
def knuth_morris_pratt(s: Any, t: Any) -> object {
    assert (t != '');
    len_s = len(s);
    len_t = len(t);
    r = [0] * len_t;
    j = r[0]=-1;
    for i in range(1, len_t) {
        while ((j >= 0) and (t[(i - 1)] != t[j])) {
            j = r[j];
        }
        j += 1;
        r[i] = j;
    }
    j = 0;
    for i in range(len_s) {
        while ((j >= 0) and (s[i] != t[j])) {
            j = r[j];
        }
        j += 1;
        if (j == len_t) {
            return ((i - len_t) + 1);
        }
    }
    return -1;
}
